--
-- Table structure for table `verbals_trials`
--

DROP TABLE IF EXISTS `verbals_trials`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `verbals_trials` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `committee_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `committee_date` date NOT NULL,
  `civility` enum('Mr','Mme','Mlle') COLLATE utf8mb4_unicode_ci NOT NULL,
  `applicant_first_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `applicant_last_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `account_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `activity` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `purpose_of_financing` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type_of_credit_id` bigint unsigned NOT NULL,
  `amount` decimal(21,2) NOT NULL,
  `duration` int NOT NULL,
  `periodicity` enum('mensual','quarterly','semi-annual','annual','in-fine') COLLATE utf8mb4_unicode_ci NOT NULL,
  `taf` double(8,2) NOT NULL,
  `administrative_fees_percentage` decimal(21,2) NOT NULL,
  `tax_fee_interest_rate` double(8,2) NOT NULL,
  `caf_id` bigint unsigned NOT NULL,
  `credit_admin_id` bigint unsigned NOT NULL,
  `credit_analyst_id` bigint unsigned NOT NULL,
  `creator_id` bigint unsigned NOT NULL,
  `validation_level` enum('credit_analyst','credit_admin','head_credit','md') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'credit_analyst',
  `status` enum('waiting','rejected','validated') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'waiting',
  `comment` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reserve` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `entity_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `release_type` enum('non-progressive','progressive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'non-progressive',
  `risk_premium_percentage` double(8,2) NOT NULL DEFAULT '0.50',
  `has_line_review_bonus` tinyint(1) NOT NULL DEFAULT '0',
  `has_insurance` tinyint(1) NOT NULL DEFAULT '0',
  `number_deferred` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `representative_phone_number` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `verbals_trials_committee_id_unique` (`committee_id`),
  KEY `verbals_trials_type_of_credit_id_foreign` (`type_of_credit_id`),
  KEY `verbals_trials_caf_id_foreign` (`caf_id`),
  KEY `verbals_trials_credit_admin_id_foreign` (`credit_admin_id`),
  KEY `verbals_trials_credit_analyst_id_foreign` (`credit_analyst_id`),
  KEY `verbals_trials_creator_id_foreign` (`creator_id`),
  CONSTRAINT `verbals_trials_caf_id_foreign` FOREIGN KEY (`caf_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `verbals_trials_creator_id_foreign` FOREIGN KEY (`creator_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `verbals_trials_credit_admin_id_foreign` FOREIGN KEY (`credit_admin_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `verbals_trials_credit_analyst_id_foreign` FOREIGN KEY (`credit_analyst_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `verbals_trials_type_of_credit_id_foreign` FOREIGN KEY (`type_of_credit_id`) REFERENCES `types_of_credit` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=95 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

